    "qNumber": 14,
    "stem": "5237 sayılı Türk Ceza Kanunu hükümleri uyarınca yaş küçüklüğünün ceza sorumluluğuna etkisine ilişkin aşağıdaki ifadelerden hangisi yanlıştır?",
